import numpy as np


def run(frames, params):
    p = params or {}
    mt = float(p.get('marker_change_px', 1.0))
    dtol = float(p.get('depth_change_mm', 0.05))
    if not (np.isfinite(mt) and 0 < mt <= 100 and np.isfinite(dtol) and 0 < dtol <= 10):
        return {'diagnosis': 'unknown', 'reason': 'invalid_thresholds'}
    fs = list(frames)[-4:]
    def scalar(x):
        if x is None:
            return None
        v = float(x)
        return v if np.isfinite(v) and abs(v) < 1e12 else None
    def rounded(x):
        v = scalar(x)
        return None if v is None else round(v, 4)
    def array(d, key):
        v = d.get(key)
        return v.astype(float, copy=False) if isinstance(v, np.ndarray) else None
    def elapsed(a, b):
        x, y = scalar(a.get('simulation_time_s')), scalar(b.get('simulation_time_s'))
        if x is not None and y is not None:
            return y - x if y > x else None
        x, y = scalar(a.get('physics_step')), scalar(b.get('physics_step'))
        h, k = scalar(a.get('physics_dt')), scalar(b.get('physics_dt'))
        return (y-x)*h if None not in (x, y, h, k) and y > x and h == k and h > 0 else None
    def markers(s):
        expected = {'marker_units': 'pixels', 'marker_coordinate_order': 'x,y',
                    'marker_origin': 'top_left', 'marker_axes': 'x_right_y_down'}
        if any(s.get(k) != v for k, v in expected.items()):
            return None
        r, d = array(s, 'marker_reference'), array(s, 'marker_displacement')
        size = s.get('image_size')
        if r is None or d is None or r.ndim != 2 or r.shape[1] != 2 or d.shape != r.shape:
            return None
        if size is None or len(size) != 2 or min(size) <= 0 or len(r) < 12:
            return None
        h, w = size
        ok = np.isfinite(r).all(1) & np.isfinite(d).all(1)
        ok &= (r[:, 0] >= 0) & (r[:, 0] < w) & (r[:, 1] >= 0) & (r[:, 1] < h)
        ok &= (np.abs(d) < 2*max(h, w)).all(1)
        if ok.mean() < 0.8:
            return None
        r, d = r[ok], d[ok]
        u, inv = np.unique(np.round(r, 3), axis=0, return_inverse=True)
        v = np.array([np.median(d[inv == j], axis=0) for j in range(len(u))])
        return (u, v) if len(u) >= 12 else None
    def compare(a, b):
        result = {'marker_px': None, 'depth_fraction': None, 'coverage': None}
        vec = None
        same = a.get('reference_kind') is not None and a.get('reference_kind') == b.get('reference_kind')
        same &= tuple(a.get('image_size', ())) == tuple(b.get('image_size', ()))
        aa, bb = markers(a), markers(b)
        if same and aa is not None and bb is not None:
            ar, ad = aa
            br, bd = bb
            distances = np.sum((ar[:, None] - br[None, :])**2, axis=2)
            j = distances.argmin(1)
            i = np.arange(len(ar))
            keep = (distances[i, j] <= 1.0) & (distances.argmin(0)[j] == i)
            coverage = float(keep.sum()/max(len(ar), len(br)))
            result['coverage'] = rounded(coverage)
            if keep.sum() >= 12 and coverage >= 0.7:
                delta = bd[j[keep]] - ad[keep]
                result['marker_px'] = float(np.median(np.linalg.norm(delta, axis=1)))
                vec = np.median(delta, axis=0)
        da, db = array(a, 'depth'), array(b, 'depth')
        native = 'native_sensor_camera_depth_not_indentation'
        good = all(s.get('depth_units') == 'mm' and s.get('depth_semantics') == native for s in (a, b))
        if good and da is not None and db is not None and da.ndim == 2 and da.shape == db.shape:
            valid = np.isfinite(da) & np.isfinite(db) & (da > 0) & (db > 0)
            if valid.size and valid.sum() >= 64 and valid.mean() >= 0.8:
                result['depth_fraction'] = float(np.mean(np.abs(db[valid]-da[valid]) > dtol))
        return result, vec
    def hand(a, b):
        a, b = a.get('state', {}), b.get('state', {})
        if any(s.get('pose_frame') != 'world' or s.get('position_units') != 'm' for s in (a, b)):
            return None
        if a.get('eef_frame') is None or a.get('eef_frame') != b.get('eef_frame'):
            return None
        x, y = array(a, 'eef_pose_wxyz'), array(b, 'eef_pose_wxyz')
        if x is None or y is None or x.shape != (7,) or y.shape != (7,):
            return None
        if not np.isfinite(x).all() or not np.isfinite(y).all() or max(np.max(np.abs(x)), np.max(np.abs(y))) > 1e6:
            return None
        q, r = np.linalg.norm(x[3:]), np.linalg.norm(y[3:])
        if min(q, r) < 1e-8:
            return None
        angle = np.degrees(2*np.arccos(np.clip(abs(np.dot(x[3:]/q, y[3:]/r)), 0, 1)))
        return [float(1000*np.linalg.norm(y[:3]-x[:3])), float(angle)]
    out = {'frames': [[i, rounded(f.get('step'))] for i, f in enumerate(fs)],
           'diagnosis': 'unknown', 'latest': None, 'strongest': None, 'reversal_frames': None,
           'applicability': 'same episode and continuous references; temporal comparisons only',
           'uncertainty': 'Tracking accuracy and cause unknown. Depth is not indentation; pixels are not force. Quiet does not establish contact absence or physical stability.'}
    intervals = []
    for i in range(1, len(fs)):
        a, b = fs[i-1], fs[i]
        t = elapsed(a, b)
        sides, vectors = [], []
        for side in ('left', 'right'):
            m, v = compare(a.get('tactile', {}).get(side, {}), b.get('tactile', {}).get(side, {})) if t else ({'marker_px': None, 'depth_fraction': None, 'coverage': None}, None)
            sides.append(m)
            vectors.append(v)
        h = hand(a, b) if t else None
        intervals.append({'frames': [i-1, i], 'dt_s': t, 'sides': sides, 'vectors': vectors, 'hand': h})
    if not intervals:
        out['diagnosis'] = 'unknown_need_two_time_advanced_frames'
        return out
    def public(z):
        return {'frames': z['frames'], 'dt_s': rounded(z['dt_s']),
                'marker_px_lr': [rounded(s['marker_px']) for s in z['sides']],
                'depth_fraction_lr': [rounded(s['depth_fraction']) for s in z['sides']],
                'match_coverage_lr': [s['coverage'] for s in z['sides']],
                'hand_mm_deg': None if z['hand'] is None else [rounded(v) for v in z['hand']]}
    last = intervals[-1]
    out['latest'] = public(last)
    known = all(s['marker_px'] is not None and s['depth_fraction'] is not None for s in last['sides'])
    if known:
        m = [s['marker_px'] >= mt for s in last['sides']]
        d = [s['depth_fraction'] > 0.01 for s in last['sides']]
        if any(x and y for x, y in zip(m, d)):
            out['diagnosis'] = 'marker_change_with_depth_support'
        elif any(m):
            out['diagnosis'] = 'marker_change_without_depth_support'
        elif any(d):
            out['diagnosis'] = 'depth_change_without_marker_support'
        else:
            h = last['hand']
            context = 'hand_unknown' if h is None else ('fixed_hand' if h[0] <= 0.2 and h[1] <= 0.1 else 'moving_hand')
            out['diagnosis'] = 'small_bilateral_change_' + context
    usable = [z for z in intervals if all(s['marker_px'] is not None for s in z['sides'])]
    if usable:
        peak = max(usable, key=lambda z: max(s['marker_px'] for s in z['sides']))
        out['strongest'] = {'frames': peak['frames'], 'marker_px_lr': [rounded(s['marker_px']) for s in peak['sides']]}
    for a, b in zip(intervals, intervals[1:]):
        reverse = True
        for j in range(2):
            x, y = a['vectors'][j], b['vectors'][j]
            sa, sb = a['sides'][j], b['sides'][j]
            if x is None or y is None or any(s['depth_fraction'] is None or s['depth_fraction'] > 0.01 for s in (sa, sb)):
                reverse = False
                continue
            nx, ny = np.linalg.norm(x), np.linalg.norm(y)
            reverse &= min(nx, ny) >= mt and nx >= 0.75*sa['marker_px'] and ny >= 0.75*sb['marker_px']
            reverse &= np.dot(x, y) < -0.8*nx*ny and np.linalg.norm(x+y) < 0.35*max(nx, ny)
        if reverse:
            out['reversal_frames'] = [a['frames'][0], a['frames'][1], b['frames'][1]]
    if out['reversal_frames'] is not None:
        out['window_evidence'] = 'bilateral_marker_reversal_without_depth_support; not sustained directional evidence'
    return out
